export const toUlaw=A=>{let t=A,e=4096,n=0,l=12,x=0;for(t<0&&(t=-t,n=128),t+=33,t>8191&&(t=8191);(t&e)!==e&&l>=5;)e>>=1,l--;return x=t>>l-4&15,~(n|l-5<<4|x)&255},fromUlaw=A=>{let o=0,t=0,e=~A;e&128&&(e&=-129,o=-1),t=((e&240)>>4)+5;const n=(1<<t|(e&15)<<t-4|1<<t-5)-33;return o===0?n:-n},toAlaw=A=>{let o=2048,t=0,e=11,n=0,l=A;for(l<0&&(l=-l,t=128),l>4095&&(l=4095);(l&o)!==o&&e>=5;)o>>=1,e--;return n=l>>(e===4?1:e-4)&15,(t|e-4<<4|n)^85},fromAlaw=A=>{let s=0,o=0,t=A^85;t&128&&(t&=-129,s=-1),o=((t&240)>>4)+4;let e=0;return o!==4?e=1<<o|(t&15)<<o-4|1<<o-5:e=t<<1|1,s===0?e:-e};
